const input = $input.first().json.body;
const ghToken = '${GITHUB_TOKEN}';
const issueNum = input.issue_number || input.issue;
if (!issueNum) { throw new Error('Missing issue or issue_number field'); }
const action = input.action || 'approve';
const labels = action === 'reject' ? ['rejected'] : ['approved', 'automation'];
const data = await this.helpers.httpRequest({
  method: 'PATCH',
  url: 'https://api.github.com/repos/${GITHUB_REPO}/issues/' + issueNum,
  headers: { 'Authorization': 'token ' + ghToken, 'User-Agent': 'n8n-automation', 'Accept': 'application/vnd.github.v3+json' },
  body: { labels: labels },
  json: true
});
return [{json: {status: action, issue: data.number, labels: labels}}];
